// Real WebView/Rust timings on the same six accepted 10k conversion workloads
// as the pure benchmark. File selection and DOM events are generated by the lane.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
const hash = (bytes) => createHash('sha256').update(bytes).digest('hex');
function time(ms) {
  return `${String(Math.floor(ms / 3600000)).padStart(2, '0')}:${String(Math.floor(ms / 60000) % 60).padStart(2, '0')}:${String(Math.floor(ms / 1000) % 60).padStart(2, '0')},${String(ms % 1000).padStart(3, '0')}`;
}
function srtCorpus() {
  let text = '';
  for (let i = 0; i < 10000; i++) {
    const n = String(i).padStart(5, '0');
    const cue = [
      `<i>Cue ${n} — 日本語 😀</i>\nSecond line`,
      `{\\an8\\k10}Cue ${n}\\NSecond line`,
      `Cue ${n} C:\\new\\here`,
      `Plain cue ${n} — été`,
    ][i % 4];
    text += `${i + 1}\n${time(i * 1500 + 1)} --> ${time(i * 1500 + 1001)}\n${cue}\n\n`;
  }
  assert.equal(
    hash(text),
    'ac467ca8e93a1f14bb97e9666e41aa602499a0d06f531d367affba8c5df1ff77',
  );
  return Buffer.from(text);
}
export async function conversionPerformance({
  restart,
  root,
  evidence,
  binary,
  record,
}) {
  const report = {
    status: 'running',
    binary,
    binarySha256: hash(await readFile(binary)),
    budgetMs: 1000,
    scope:
      'Actual WebView/Rust/files, six accepted 10k pairs, five cycles. Generated DOM/IPC and supplied file choices; no physical-input, native-picker or GPU-presentation latency claim. Preparation is separately bounded by the 10-second worker deadline.',
    cases: [],
  };
  const save = () =>
    writeFile(
      join(evidence, 'conversion-performance.json'),
      JSON.stringify(report, null, 2) + '\n',
    );
  try {
    for (const source of ['srt', 'ass', 'ssa']) {
      const bytes =
        source === 'srt'
          ? srtCorpus()
          : await readFile(
              resolve(`tests/fixtures/generated/ass-ssa/10000.${source}`),
            );
      for (const target of ['srt', 'ass', 'ssa']) {
        if (source === target) continue;
        const path = join(
          root,
          `conversion-10000-${source}-${target}.${source}`,
        );
        const outputs = Array.from({ length: 5 }, (_, i) =>
          join(root, `converted-10000-${source}-${target}-${i}.${target}`),
        );
        await writeFile(path, bytes);
        const browser = await restart([
          { kind: 'subtitles', path },
          ...outputs.map((path) => ({
            kind: `export${target[0].toUpperCase()}${target.slice(1)}`,
            path,
          })),
          { kind: 'subtitles', path: outputs.at(-1) },
        ]);
        await browser.execute(() => {
          const invoke = window.__TAURI__.core.invoke;
          window.__conversionBench = {
            invoke,
            state: () =>
              invoke('document_action', {
                action: { kind: 'status' },
                generation: 0,
                revision: 0,
              }),
            frame: () => new Promise((r) => requestAnimationFrame(r)),
            button: (label) =>
              [...document.querySelectorAll('button')].find(
                (b) => b.textContent.trim() === label && !b.disabled,
              ),
            wait: async (probe) => {
              const end = performance.now() + 12000;
              while (performance.now() < end) {
                const value = await probe();
                if (value) return value;
                await new Promise((r) => setTimeout(r, 5));
              }
              throw new Error('Conversion benchmark did not settle');
            },
            ready: () =>
              document.querySelector('main').getAttribute('aria-busy') ===
                'false' &&
              !document.querySelector('dialog[open]') &&
              [...document.querySelectorAll('button')].some(
                (b) =>
                  b.textContent.trim() === 'Convert subtitles…' && !b.disabled,
              ),
            select: (label, value) => {
              const field = document.querySelector(`[aria-label="${label}"]`);
              field.value = value;
              field.dispatchEvent(new Event('change', { bubbles: true }));
            },
          };
        });
        const openMs = await browser.execute(async () => {
          const b = window.__conversionBench,
            at = performance.now();
          await window.__TAURI__.event.emit(
            'workspace-action',
            'openSubtitles',
          );
          await b.wait(
            async () => (await b.state()).cues.length === 10000 && b.ready(),
          );
          await b.frame();
          return performance.now() - at;
        });
        const result = {
          source,
          target,
          cues: 10000,
          inputSha256: hash(bytes),
          openMs,
          dialogMs: [],
          preparationMs: [],
          publicationMs: [],
          closeMs: [],
          outputSha256: [],
        };
        report.cases.push(result);
        await save();
        for (let run = 0; run < 5; run++) {
          const timing = await browser.execute(
            async (source, target, path) => {
              const b = window.__conversionBench;
              await b.wait(b.ready);
              const before = await b.state(),
                opening = performance.now();
              b.button('Convert subtitles…').click();
              await b.wait(() =>
                document.querySelector('[aria-label="Conversion format"]'),
              );
              await b.frame();
              const dialogMs = performance.now() - opening;
              b.select('Conversion format', target);
              if (source === 'srt') b.select('Conversion precision', 'nearest');
              await b.frame();
              const preparing = performance.now();
              b.button('Review conversion').click();
              await b.wait(() => b.button('Choose new output file…'));
              await b.frame();
              const preparationMs = performance.now() - preparing;
              const report = document.querySelector(
                '[aria-label="Conversion loss report"]',
              );
              if (!report.textContent.includes('10000 cues'))
                throw new Error('Incomplete report count');
              for (const issue of report.querySelectorAll('article'))
                if (issue.querySelectorAll('li').length > 8)
                  throw new Error('Unbounded report examples');
              const publishing = performance.now();
              b.button('Choose new output file…').click();
              await b.wait(() =>
                document
                  .querySelector('[aria-label="Conversion exported"]')
                  ?.textContent.includes(path),
              );
              await b.frame();
              const publicationMs = performance.now() - publishing;
              if (JSON.stringify(await b.state()) !== JSON.stringify(before))
                throw new Error('Export changed document state');
              const closing = performance.now();
              b.button('Close conversion').click();
              await b.wait(b.ready);
              await b.frame();
              return {
                dialogMs,
                preparationMs,
                publicationMs,
                closeMs: performance.now() - closing,
              };
            },
            source,
            target,
            outputs[run],
          );
          for (const [name, value] of Object.entries(timing))
            result[name].push(value);
          const output = await readFile(outputs[run]);
          result.outputSha256.push(hash(output));
          if (run === 0)
            await browser.saveScreenshot(
              join(evidence, `conversion-10000-${source}-${target}.png`),
            );
        }
        assert.equal(
          new Set(result.outputSha256).size,
          1,
          'Repeated export changed output bytes',
        );
        const rejectedPath = join(
          root,
          `refused-${source}-${target}.${target}`,
        );
        const guards = await browser.execute(
          async (target, rejectedPath) => {
            const b = window.__conversionBench,
              doc = await b.state();
            const options = {
              target,
              precision: doc.format ? 'exact' : 'nearest',
            };
            const args = {
              generation: doc.generation,
              revision: doc.revision,
              options,
            };
            const id = await b.invoke('conversion_start', args),
              cancelling = performance.now();
            await b.invoke('conversion_cancel', { id });
            await b.frame();
            const cancelMs = performance.now() - cancelling;
            await b.wait(
              async () =>
                (await b.invoke('conversion_view', { id })).phase ===
                'cancelled',
            );
            const cancelDrainedMs = performance.now() - cancelling;
            let refused = false;
            try {
              await b.invoke('conversion_publish', { id, path: rejectedPath });
            } catch {
              refused = true;
            }
            if (!refused) throw new Error('Cancelled conversion published');
            const stale = await b.invoke('conversion_start', args);
            await b.wait(
              async () =>
                (await b.invoke('conversion_view', { id: stale })).phase ===
                'reviewing',
            );
            const changing = performance.now(),
              field = document.querySelector('[aria-label="Subtitle text"]');
            field.value = doc.cues[0].text + ' stale';
            field.dispatchEvent(new Event('input', { bubbles: true }));
            await b.frame();
            b.button('Apply edit').click();
            await b.wait(
              async () =>
                (await b.state()).revision === doc.revision + 1 && b.ready(),
            );
            if (
              (await b.invoke('conversion_view', { id: stale })).phase !==
              'stale'
            )
              throw new Error('Edit retained current review');
            refused = false;
            try {
              await b.invoke('conversion_publish', {
                id: stale,
                path: rejectedPath,
              });
            } catch {
              refused = true;
            }
            if (!refused) throw new Error('Stale conversion published');
            await b.frame();
            const staleMs = performance.now() - changing;
            b.button('Undo edit').click();
            await b.wait(
              async () =>
                (await b.state()).revision === doc.revision + 2 && b.ready(),
            );
            if ((await b.state()).dirty)
              throw new Error('Guard cleanup did not restore saved state');
            return { cancelMs, cancelDrainedMs, staleMs };
          },
          target,
          rejectedPath,
        );
        await assert.rejects(readFile(rejectedPath), { code: 'ENOENT' });
        Object.assign(result, guards);
        const reopened = await browser.execute(async (source) => {
          const b = window.__conversionBench,
            before = await b.state();
          await window.__TAURI__.event.emit(
            'workspace-action',
            'openSubtitles',
          );
          const after = await b.wait(async () => {
            const d = await b.state();
            return d.generation !== before.generation && b.ready() && d;
          });
          if (after.cues.length !== 10000) throw new Error('Export lost cues');
          const delta = source === 'srt' ? 1 : 0;
          for (let i = 0; i < after.cues.length; i++)
            if (
              after.cues[i].startMs !== before.cues[i].startMs - delta ||
              after.cues[i].endMs !== before.cues[i].endMs - delta
            )
              throw new Error(`Unexpected output timing at ${i}`);
          return {
            cues: after.cues.length,
            format: after.format?.name ?? 'srt',
            dirty: after.dirty,
          };
        }, source);
        assert.equal(reopened.format, target);
        assert.equal(reopened.dirty, false);
        assert.deepEqual(await readFile(path), bytes);
        result.reopen = reopened;
        for (const [name, values] of Object.entries({
          openMs: [openMs],
          dialogMs: result.dialogMs,
          publicationMs: result.publicationMs,
          closeMs: result.closeMs,
          cancelMs: [result.cancelMs],
          cancelDrainedMs: [result.cancelDrainedMs],
          staleMs: [result.staleMs],
        }))
          assert.ok(
            values.every((v) => v < 1000),
            `${source}/${target} ${name} exceeded 1000 ms: ${values}`,
          );
        assert.ok(result.preparationMs.every((v) => v < 10000));
        await save();
        await record({ step: `10k conversion ${source} to ${target}`, result });
      }
    }
    report.status = 'passed';
    await save();
  } catch (error) {
    report.status = 'failed';
    report.error = String(error.stack ?? error);
    await save();
    throw error;
  }
}
